node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get order details
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = 'ORD-D7E869'\").get();
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

// Get order items
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-D7E869'\").all();
console.log('\n=== ORDER ITEMS ===');
items.forEach(i => console.log(JSON.stringify(i, null, 2)));

// Get order payments
try {
  const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-D7E869'\").all();
  console.log('\n=== ORDER PAYMENTS ===');
  payments.forEach(p => console.log(JSON.stringify(p, null, 2)));
} catch(e) { console.log('No payments table or no match'); }

// Get order fulfillments
try {
  const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = 'ORD-D7E869'\").all();
  console.log('\n=== ORDER FULFILLMENTS ===');
  fulfillments.forEach(f => console.log(JSON.stringify(f, null, 2)));
} catch(e) { console.log('No fulfillments table or no match'); }

// Get warranty info
try {
  const warranties = db.prepare(\"SELECT * FROM warranties WHERE order_id = 'ORD-D7E869'\").all();
  console.log('\n=== WARRANTIES ===');
  warranties.forEach(w => console.log(JSON.stringify(w, null, 2)));
} catch(e) { console.log('No warranties or no match'); }
"

