const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const transaction = db.transaction(() => {
    // 1. Update gift_wrap on CI-0023
    db.prepare('UPDATE cart_items SET gift_wrap = 1 WHERE cart_item_id = ?').run('CI-0023');

    // 2. Recompute cart totals
    // subtotal stays 49 (1 x \$49, quantity unchanged)
    // gift_wrap_fee = 1 wrapped item × \$5 = 5
    // discount_amount = 0 (no promos)
    // loyalty_discount = 24 (already applied)
    // Check 50% cap: 50% of subtotal (49) = 24 — loyalty_discount (24) <= 24 ✓ no clamping needed
    // shipping_cost = 6
    // total = 49 + 5 + 6 - 0 - 24 = 36

    db.prepare(\`
        UPDATE carts 
        SET gift_wrap_fee = 5,
            total = subtotal + 5 + shipping_cost - discount_amount - loyalty_discount
        WHERE customer_id = ?
    \`).run('user_d3d5d0c8');

    // Verify
    const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id = 'user_d3d5d0c8'\").get();
    const item = db.prepare(\"SELECT * FROM cart_items WHERE cart_item_id = 'CI-0023'\").get();
    const customer = db.prepare(\"SELECT loyalty_points FROM users WHERE user_id = 'user_d3d5d0c8'\").get();

    return { cart, item, customer };
});

const r = transaction();

console.log('=== UPDATED CART ITEM ===');
console.log('cart_item_id:', r.item.cart_item_id);
console.log('product_id:', r.item.product_id);
console.log('quantity:', r.item.quantity);
console.log('gift_wrap:', r.item.gift_wrap);

